WITH Ranked AS (
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY Email ORDER BY CustomerId) AS rn
    FROM dbo.Customers
)
SELECT * FROM Ranked WHERE rn > 1;

IF EXISTS (
    SELECT 1 FROM dbo.Orders
    HAVING SUM(CASE WHEN ShippingAddress IS NULL THEN 1 ELSE 0 END) > 50
)
    SELECT 'Threshold exceeded';
